"""Care Companion chat: typed, spoken and button input; text and voice output."""
import uuid
from datetime import datetime

import streamlit as st

from src.ai.assistant import answer
from src.services import reminder_service
from src.ui.theme import badge
from src.voice.component import voice_widget

SOURCES = {"app_data": ("Your saved data", "ok"),
           "knowledge": ("From the knowledge base", "ok"),
           "general": ("Local reply (no AI text)", "ai-off"),
           "safety": ("Safety note", "attention"),
           "gemini": ("AI-generated by Gemini", "ai-on"),
           "gemini_cache": ("AI-generated by Gemini (saved earlier answer)", "ai-on")}
QUICK = ["What medicines do I take today?", "When is my next appointment?", "Who is my caregiver?"]
MAX_MESSAGES, MAX_CHARS = 20, 300


def _handle(db_path, elder, caregiver, manager, text: str) -> None:
    ss = st.session_state
    text = (text or "").strip()[:MAX_CHARS]
    if not text:
        return
    reply = answer(db_path, elder, caregiver, text, manager, datetime.now())
    ss["chat"] += [{"role": "user", "text": text},
                   {"role": "assistant", "text": reply.text, "speech": reply.speech, "source": reply.source,
                    "notice": reply.notice, "trace": reply.trace,
                    "sources": list(reply.sources), "action": reply.action}]
    ss["chat"] = ss["chat"][-MAX_MESSAGES:]
    ss["speak_once"] = {"id": uuid.uuid4().hex, "text": reply.speech}


def _resolve_reminder(db_path, elder, accept: bool) -> None:
    ss = st.session_state
    msg = next((m for m in reversed(ss["chat"]) if m.get("action")), None)
    if not msg:
        return
    if accept:
        a = msg["action"]
        reminder_service.add_reminder(db_path, elder["id"], a["task"], a["time"])
        text = f"Saved. I will show \"{a['task']}\" on your dashboard every day at {a['time']}."
    else:
        text = "Okay, I have not saved it."
    msg["action"] = None
    ss["chat"].append({"role": "assistant", "text": text, "speech": text, "source": "general", "notice": None,
                       "trace": {"route": "reminder confirmation by the person"}, "sources": [], "action": None})
    ss["speak_once"] = {"id": uuid.uuid4().hex, "text": text}


def render(db_path, elder, caregiver, manager) -> None:
    ss = st.session_state
    ss.setdefault("chat", [])
    ss.setdefault("auto_speak", True)

    st.title("Care Companion")
    st.write("Ask me about your medicines, appointments or your caregiver. You can speak, type, or tap a button.")

    last_speech = next((m["speech"] for m in reversed(ss["chat"]) if m["role"] == "assistant"), "")
    with st.container(key="card_voice"):
        voice = voice_widget(last_speech, ss.pop("speak_once", None), ss["auto_speak"])
        st.checkbox("Read replies aloud", key="auto_speak")
        st.caption("Voice uses your browser's speech features. In Chrome and Edge, speech is turned into text "
                   "by the browser's online speech service. Voice itself never uses Gemini.")

    new_text = None
    if voice and voice.get("id") != ss.get("voice_last_id"):
        ss["voice_last_id"] = voice.get("id")
        new_text = voice.get("text")
    cols = st.columns(len(QUICK))
    for col, q in zip(cols, QUICK):
        if col.button(q, key=f"q_{q}", width="stretch"):
            new_text = q
    if prompt := st.chat_input("Type your question here"):
        new_text = prompt
    if new_text:
        _handle(db_path, elder, caregiver, manager, new_text)
        st.rerun()

    for m in ss["chat"]:
        with st.chat_message(m["role"]):
            if m["role"] == "assistant":
                label, kind = SOURCES[m["source"]]
                st.markdown(badge(label, kind), unsafe_allow_html=True)
            st.markdown(m["text"])
            if m["role"] == "assistant":
                if m.get("notice"):
                    st.caption(m["notice"])
                if m.get("sources"):
                    st.caption("Sources: " + "; ".join(m["sources"]))
                with st.expander("How was this answered?"):
                    st.json(m["trace"])
    if ss["chat"] and ss["chat"][-1].get("action"):
        b1, b2 = st.columns(2)
        b1.button("Yes, save the reminder", key="rem_yes", on_click=_resolve_reminder, args=(db_path, elder, True), width="stretch")
        b2.button("No, do not save", key="rem_no", on_click=_resolve_reminder, args=(db_path, elder, False), width="stretch")
    if ss["chat"]:
        if st.button("Clear conversation"):
            ss["chat"] = []
            st.rerun()
    st.caption(f"{manager.status().label}. Safety messages and answers about your medicines, appointments and "
               "caregiver come from fixed rules and your saved records, never from AI text. This companion "
               "cannot give medical advice, diagnose, or change medicines.")
